test('seek observer rejects a readonly or unavailable control before dispatch and retains actual before/after failure positions',async()=>{
 const {observeVsqTailSeek}=await observationHelpers();
 for(const mutation of [s=>s.control.tag='PROGRESS',s=>s.control.type='text',s=>s.control.min='',s=>s.control.max='4000',s=>s.control.step='1',s=>s.control.disabled=true,s=>s.control.connected=false]){
  const state=syntheticSeekState(),evidence={};mutation(state);let actions=0;
  await assert.rejects(observeVsqTailSeek({document:{},endMs:runtime.runtime.end_ms,lastNoteEndMs:runtime.runtime.notes[0].end_ms,native:async()=>actions++,until:async()=>{throw Error('No wait should start');},frame:async()=>{},snapshot:()=>structuredClone(state),events:[],evidence}),/before=0ms, after=0ms/);
  assert.equal(actions,0);assert.equal(evidence.before.positionMs,0);assert.equal(evidence.after.positionMs,0);assert.equal(evidence.eventEnd,0);
 }
});

test('seek observer uses one pointer action and two existing frames, retains unchanged-clock timeouts and catches autoaudio before Play',async()=>{
 const {observeVsqTailSeek}=await observationHelpers();
 for(const mode of ['success','unchanged','moving','autoaudio']){
  const state=syntheticSeekState(),evidence={},events=[],actions=[];let frames=0;
  const run=()=>observeVsqTailSeek({document:{getElementById:id=>({id})},endMs:runtime.runtime.end_ms,lastNoteEndMs:Math.max(...runtime.runtime.notes.map(note=>note.end_ms)),native:async(kind,node)=>{actions.push([kind,node.id]);events.push(...syntheticSeekEvents());if(mode!=='unchanged'){state.positionMs=runtime.runtime.end_ms/2;state.renderer='paused';}if(mode==='autoaudio')state.audio.worklet.started++;return 10;},until:async(condition,label,...extra)=>{assert.equal(label,'real seek into source tail');assert.deepEqual(extra,[],'Seek keeps the existing bounded default wait');if(!condition())throw Error('original bounded deadline');},frame:async()=>{frames++;if(mode==='moving')state.positionMs++;},snapshot:()=>structuredClone(state),events,evidence});
  if(mode==='success'){await run();assert.equal(evidence.before.positionMs,0);assert.equal(evidence.after.positionMs,runtime.runtime.end_ms/2);assert.equal(evidence.beforePlay.positionMs,evidence.after.positionMs);assert.equal(evidence.pointerAction,10);assert.equal(frames,2);}
  else{await assert.rejects(run(),mode==='unchanged'?/before=0ms, after=0ms.*original bounded deadline/:mode==='moving'?/clock moved/:/auto-started audio/);assert.equal(evidence.after.positionMs,state.positionMs);}
  assert.deepEqual(actions,[['click','progress']]);assert.equal(evidence.eventEnd,5);
 }
});

