test('seek completion waits for the actual ended renderer within the original deadline after range reaches source end',async()=>{
 const source=await readFile(new URL('../crates/desktop-shell/vsq-song-acceptance.js',import.meta.url),'utf8'),section=source.indexOf("checkpoint('listen-seek-tail')"),begin=source.indexOf('await until(',source.indexOf('report.seek.playEventEnd=',section)),end=source.indexOf(';await silence(',begin),nodes={progress:evidenceClockNode(runtime.runtime.end_ms,{durationMs:runtime.runtime.end_ms,running:true,rawValue:'4083.33716666667'}),'clean-song-stage':{dataset:{rendererState:'playing'}}};
 let calls=0;const wait=runInNewContext(`async()=>{${source.slice(begin,end+1)}}`,{$:id=>nodes[id],runtime,nativePlaybackEnded:endMs=>{const clock=readPlaybackClock(nodes.progress);return clock.positionMs===endMs&&clock.completed&&clock.phase==='ended';},until:async(condition,label,timeout)=>{
  calls++;assert.equal(label,'seeked native end');assert.equal(timeout,7000);assert.equal(condition(),false,'A clamped range at end does not complete a still-playing renderer');
  nodes['clean-song-stage'].dataset.rendererState='paused';setEvidencePlaybackClock(nodes.progress,runtime.runtime.end_ms,{durationMs:runtime.runtime.end_ms,hasStarted:true});assert.equal(condition(),false,'A paused endpoint is not natural completion');
  nodes['clean-song-stage'].dataset.rendererState='ended';setEvidencePlaybackClock(nodes.progress,runtime.runtime.end_ms-1,{durationMs:runtime.runtime.end_ms,hasStarted:true});assert.equal(condition(),false,'Ended state must also have the exact source clock');
  setEvidencePlaybackClock(nodes.progress,runtime.runtime.end_ms,{durationMs:runtime.runtime.end_ms,completed:true,rawValue:'4083.33716666667'});assert.equal(condition(),true);
 }});await wait();assert.equal(calls,1,'End grace uses the existing bounded wait rather than a fixed sleep or retry');
});


