 const rows=[sample(-50,'countdown'),sample(-0.125,null),sample(0,null),...base.slice(1)];rows.at(-1).rangeValue='4083.33716666667';validateVsqFollowing(rows,runtime);
 assert.equal(rows[1].positionMs,0);assert.equal(rows[1].transportPositionMs,-0.125);assert.deepEqual(rows[1].ids,[]);assert.equal(Number(rows.at(-1).rangeValue)===runtime.runtime.end_ms,false);
 for(const change of [r=>delete r[1].clock,r=>r[1].clock.version=2,r=>{r[1].clock.transportPositionMs=0;r[1].transportPositionMs=0;},r=>r[1].ids=[...base[0].ids],r=>r.at(-1).clock.positionMs=Number(r.at(-1).rangeValue)]){const bad=structuredClone(rows);change(bad);assert.throws(()=>validateVsqFollowing(bad,runtime));}
